import { test, expect } from '@playwright/test';

test.describe('File Upload Queue - Remove File Before Submission', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should successfully remove a file from the upload queue before submission', async ({ page }) => {
    // Setup: Upload multiple files
    const fileInput = page.getByLabel('Upload files');
    await fileInput.setInputFiles('playwright/fixtures/test-file-1.pdf');
    await fileInput.setInputFiles('playwright/fixtures/test-file-2.pdf');
    await fileInput.setInputFiles('playwright/fixtures/test-file-3.pdf');

    // Verify all files are in the queue
    const queueItems = page.getByRole('listitem', { name: /file/i });
    await expect(queueItems).toHaveCount(3);

    // Verify file names are displayed
    const fileNames = page.getByText(/test-file-1\.pdf|test-file-2\.pdf|test-file-3\.pdf/);
    await expect(fileNames).toBeVisible();

    // Action: Remove the middle file (test-file-2.pdf)
    const removeButton = page.getByRole('button', { name: /remove/i });
    await removeButton.click();

    // Verify the file is removed from the queue
    const updatedQueueItems = page.getByRole('listitem', { name: /file/i });
    await expect(updatedQueueItems).toHaveCount(2);

    // Verify the removed file name is no longer visible
    const removedFileName = page.getByText('test-file-2.pdf');
    await expect(removedFileName).not.toBeVisible();

    // Verify remaining files are still visible
    const remainingFileNames = page.getByText(/test-file-1\.pdf|test-file-3\.pdf/);
    await expect(remainingFileNames).toBeVisible();

    // Action: Submit the remaining files
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify success message
    const successMessage = page.getByText(/files submitted successfully/i);
    await expect(successMessage).toBeVisible();
  });

  test('should handle removing the last file and prevent submission', async ({ page }) => {
    // Setup: Upload a single file
    const fileInput = page.getByLabel('Upload files');
    await fileInput.setInputFiles('playwright/fixtures/test-file-single.pdf');

    // Verify file is in queue
    const queueItems = page.getByRole('listitem', { name: /file/i });
    await expect(queueItems).toHaveCount(1);

    // Action: Remove the only file
    const removeButton = page.getByRole('button', { name: /remove/i });
    await removeButton.click();

    // Verify queue is empty
    const emptyQueue = page.getByRole('listitem', { name: /file/i });
    await expect(emptyQueue).toHaveCount(0);

    // Verify empty state message is displayed
    const emptyState = page.getByText(/no files in queue/i);
    await expect(emptyState).toBeVisible();

    // Action: Attempt to submit with empty queue
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/please upload files to submit/i);
    await expect(errorMessage).toBeVisible();

    // Verify submission was not successful
    const successMessage = page.getByText(/files submitted successfully/i);
    await expect(successMessage).not.toBeVisible();
  });
});
